import json, sys
from playwright.sync_api import sync_playwright

URL = 'file:///workspace/chasen-writing/drafts/ai-design-skills-runs/repo-seed/runs/2026-10-29-r2/06-huashu-design/index.html'

JS = r"""
() => {
  const parse = (s) => {
    const m = s.match(/rgba?\(([^)]+)\)/); if(!m) return null;
    const p = m[1].split(/[\s,\/]+/).filter(Boolean).map(Number);
    return {r:p[0],g:p[1],b:p[2],a:p.length>3?p[3]:1};
  };
  const lum = (c) => { const f=(v)=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}; return 0.2126*f(c.r)+0.7152*f(c.g)+0.0722*f(c.b); };
  const ratio = (a,b) => { const x=lum(a), y=lum(b); return (Math.max(x,y)+0.05)/(Math.min(x,y)+0.05); };
  const mix = (fg,bg) => ({r:fg.r*fg.a+bg.r*(1-fg.a), g:fg.g*fg.a+bg.g*(1-fg.a), b:fg.b*fg.a+bg.b*(1-fg.a), a:1});
  const bgOf = (el) => {
    let chain=[]; let e=el;
    while(e && e.nodeType===1){ chain.push(e); e=e.parentElement; }
    for(const x of chain){ const c=parse(getComputedStyle(x).backgroundColor); if(c && c.a>0.9) return c; }
    return {r:255,g:255,b:255,a:1};
  };
  const opOf = (el) => { let o=1,e=el; while(e&&e.nodeType===1){o*=parseFloat(getComputedStyle(e).opacity); e=e.parentElement;} return o; };
  const out=[];
  for(const el of document.querySelectorAll('body *')){
    const own = Array.from(el.childNodes).filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();
    if(!own || own.length<1) continue;
    const r=el.getBoundingClientRect(); if(r.width<=0||r.height<=0) continue;
    const cs=getComputedStyle(el); if(cs.visibility==='hidden'||cs.display==='none') continue;
    const op=opOf(el); if(op<0.05) continue;
    const fg=parse(cs.color); const bg=bgOf(el); const eff=mix({...fg,a:fg.a*op},bg);
    const cr=ratio(eff,bg);
    const fs=parseFloat(cs.fontSize); const fw=parseInt(cs.fontWeight)||400;
    const large=fs>=24||(fs>=18.66&&fw>=700);
    if(cr < (large?3:4.5)) out.push({text:own.slice(0,32), cls:el.className||el.tagName, fs, fw, color:cs.color, bg:`rgb(${bg.r},${bg.g},${bg.b})`, ratio:Math.round(cr*100)/100});
  }
  return out;
}
"""

with sync_playwright() as pw:
