        p.on('console', lambda m: errs.append('console: '+m.text) if m.type=='error' else None)
        p.goto(URL, wait_until='load')
        p.wait_for_timeout(4200)
        m = p.evaluate("""() => ({
          scrollW: document.documentElement.scrollWidth,
          innerW: innerWidth,
          docH: document.documentElement.scrollHeight,
          over: Array.from(document.querySelectorAll('body *')).filter(e=>{const r=e.getBoundingClientRect(); return r.right>innerWidth+1 && getComputedStyle(e).position!=='fixed' && r.width>0;}).slice(0,12).map(e=>({tag:e.tagName,cls:(e.className||'').toString().slice(0,50),right:Math.round(e.getBoundingClientRect().right)})),
          fonts: {
            schibsted: document.fonts.check('16px "Schibsted Grotesk"'),
            newsreader: document.fonts.check('italic 16px "Newsreader"'),
            notoSans: document.fonts.check('16px "Noto Sans SC"'),
            notoSerif: document.fonts.check('16px "Noto Serif SC"'),
