          },
          h1: (()=>{const e=document.querySelector('h1'); const r=e.getBoundingClientRect(); return {w:Math.round(r.width),h:Math.round(r.height),fs:getComputedStyle(e).fontSize, top:Math.round(r.top)}})(),
          hero: Math.round(document.querySelector('.hero').getBoundingClientRect().height),
          appW: Math.round(document.querySelector('.app').getBoundingClientRect().width),
          workTop: Math.round(document.querySelector('#work').getBoundingClientRect().top)
        })""")
        print(f'== {w}x{h}', json.dumps(m, ensure_ascii=False))
        if w==1440:
            low = p.evaluate(JS)
            print('LOW CONTRAST', len(low))
            for x in low: print('  ', x)
        print('ERRORS', errs)
        p.close()
    b.close()
