cd /tmp && python3 - <<'PY'
import re
css=open('/tmp/gf.css').read()
# collect @font-face blocks for Noto Sans SC 400 with unicode-range containing 4e2d
blocks=re.findall(r'@font-face \{(.*?)\}', css, re.S)
for b in blocks:
    if "Noto Sans SC" in b and 'font-weight: 400' in b:
        m=re.search(r'unicode-range: ([^;]+);', b); u=m.group(1) if m else ''
        # check 4e2d
        hit=False
        for part in u.split(','):
            part=part.strip().replace('U+','')
            if not part: continue
            if '-' in part:
                a,c=part.split('-'); 
                try:
                    if int(a,16)<=0x4e2d<=int(c,16): hit=True
                except: pass
        if hit:
            print(re.search(r'url\((.*?)\)', b).group(1)); break
PY

